<template>
  <main class="min-h-[calc(100vh-72px)] bg-[#F4F5F7] px-4 py-6 sm:px-6 lg:px-8"><div class="mx-auto max-w-[1440px]">
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm text-[#737780]">System administration</p><h1 class="mt-1 text-2xl font-semibold text-[#25272B]">System overview</h1><p class="mt-1 text-sm text-[#737780]">Manage accounts and roles, and review administrative activity.</p></div><button class="primary" @click="openCreate"><UserPlus :size="17" /> Create user</button></div>
    <ErrorMessage class="mt-4" :message="overview.error || users.error || saver.error || activity.error" /><PageLoader v-if="overview.loading && !overview.data" />
    <template v-if="overview.data"><section class="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4 xl:grid-cols-7"><article v-for="card in cards" :key="card.label" class="rounded-xl border border-[#E4E6EA] bg-white p-4"><p class="text-xs font-medium text-[#737780]">{{ card.label }}</p><p class="mt-3 text-2xl font-semibold tabular-nums text-[#25272B]">{{ card.value }}</p></article></section>
      <section class="mt-6 overflow-hidden rounded-xl border border-[#E4E6EA] bg-white"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-[#ECEDEF] px-5 py-4"><div><h2 class="font-semibold text-[#25272B]">Website and system users</h2><p class="mt-1 text-xs text-[#858891]">Assign one application role per account.</p></div><input v-model="search" class="field max-w-sm" type="search" placeholder="Search name or email" aria-label="Search users" /></div><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-[#FAFAFB] text-[11px] uppercase tracking-wide text-[#858891]"><tr><th class="px-5 py-3">User</th><th class="px-4 py-3">Account type</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Last login</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-[#F0F1F3]"><tr v-for="user in users.data?.users || []" :key="user.name" class="hover:bg-[#FCFCFD]"><td class="px-5 py-3.5"><p class="font-semibold text-[#33353A]">{{ user.full_name || user.name }}</p><p class="mt-0.5 text-xs text-[#858891]">{{ user.name }}</p></td><td class="px-4 py-3.5 text-[#555860]">{{ user.user_type }}</td><td class="px-4 py-3.5">{{ roleLabel(user.roles?.[0]) }}</td><td class="px-4 py-3.5"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="user.enabled ? 'bg-[#EAF5EE] text-[#267344]' : 'bg-[#F1F1F2] text-[#737780]'">{{ user.enabled ? 'Active' : 'Inactive' }}</span></td><td class="px-4 py-3.5 text-[#555860]">{{ dateLabel(user.last_login) }}</td><td class="px-5 py-3.5"><div class="flex justify-end gap-2"><button class="quiet" @click="viewActivity(user)">Activity</button><button class="quiet" @click="openEdit(user)">Edit</button></div></td></tr><tr v-if="!users.loading && !users.data?.users?.length"><td colspan="6" class="px-5 py-10 text-center text-sm text-[#737780]">No users found.</td></tr></tbody></table></div><div class="flex items-center justify-between border-t border-[#ECEDEF] px-5 py-3 text-xs text-[#737780]"><span>{{ users.data?.total || 0 }} accounts</span><button v-if="users.data?.total > 50" class="quiet" @click="loadUsers(users.data.start + 50)">Load more</button></div></section>
      <div class="mt-6 grid gap-5 lg:grid-cols-[1.4fr_0.8fr]"><section class="overflow-hidden rounded-xl border border-[#E4E6EA] bg-white"><div class="flex items-center justify-between border-b border-[#ECEDEF] px-5 py-4"><div><h2 class="font-semibold text-[#25272B]">Recent activity</h2><p class="mt-1 text-xs text-[#858891]">Account and service activity metadata</p></div><router-link :to="{ name: 'AuditLogs' }" class="text-sm font-semibold text-[#A10E24] hover:underline">Full audit log</router-link></div><ActivityTable :rows="overview.data.recent_activities" /></section><section class="rounded-xl border border-[#E4E6EA] bg-white p-5"><h2 class="font-semibold text-[#25272B]">Administration tools</h2><p class="mt-1 text-xs text-[#858891]">Manage roles and system settings in Frappe Desk.</p><div class="mt-4 grid gap-2"><a class="tool-link" href="/app/role">Role management <ExternalLink :size="15" /></a><a class="tool-link" href="/app/permission-manager">Access control <ExternalLink :size="15" /></a><a class="tool-link" href="/app/system-settings">System configuration <ExternalLink :size="15" /></a></div><p class="mt-4 rounded-lg bg-[#F4F5F7] px-3 py-2.5 text-xs leading-5 text-[#62656D]">Clinical session records and baseline answers cannot be edited from the System Administrator role.</p><p class="mt-2 text-xs text-[#737780]">Audit access is limited to System Administrators and KRCS Data Protection Officers.</p></section></div>
    </template>
  </div>
  <div v-if="dialogOpen" class="fixed inset-0 z-[70] flex items-center justify-center bg-[#17191F]/40 p-4" @click.self="dialogOpen = false"><section class="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-5 shadow-xl"><div class="flex items-start justify-between"><div><h2 class="text-lg font-semibold text-[#25272B]">{{ editing ? 'Update user' : 'Create user' }}</h2><p class="mt-1 text-sm text-[#737780]">Enter account details and assign one role.</p></div><button class="quiet" aria-label="Close" @click="dialogOpen = false"><X :size="18" /></button></div><form class="mt-5 grid gap-4" @submit.prevent="saveUser"><label class="label">Email / username<input v-model="form.name" class="field mt-1" type="email" required :disabled="editing" /></label><div class="grid gap-4 sm:grid-cols-2"><label class="label">First name<input v-model="form.first_name" class="field mt-1" required /></label><label class="label">Last name<input v-model="form.last_name" class="field mt-1" /></label></div><div class="grid gap-4 sm:grid-cols-2"><label class="label">Account type<select v-model="form.user_type" class="field mt-1"><option>System User</option><option>Website User</option></select></label><label class="label">Role<select v-model="form.role" class="field mt-1" required><option v-for="role in roles" :key="role" :value="role">{{ roleLabel(role) }}</option></select></label></div><label v-if="!editing" class="label">Initial password<input v-model="form.password" class="field mt-1" type="password" minlength="8" required autocomplete="new-password" /></label><label v-if="editing" class="flex items-center gap-2 text-sm text-[#444850]"><input v-model="form.enabled" type="checkbox" class="h-4 w-4 accent-[#C8102E]" /> Account active</label><div class="flex justify-end gap-2 pt-2"><button type="button" class="secondary" @click="dialogOpen = false">Cancel</button><button class="primary" type="submit" :disabled="saver.loading">{{ saver.loading ? 'Saving…' : 'Save user' }}</button></div></form></section></div>
  <div v-if="activityUser" class="fixed inset-0 z-[70] flex items-center justify-center bg-[#17191F]/40 p-4" @click.self="activityUser = null"><section class="max-h-[85vh] w-full max-w-3xl overflow-hidden rounded-2xl bg-white shadow-xl"><div class="flex items-start justify-between border-b border-[#ECEDEF] px-5 py-4"><div><h2 class="font-semibold text-[#25272B]">User activity</h2><p class="mt-1 text-sm text-[#737780]">{{ activityUser.full_name || activityUser.name }} · {{ activityUser.name }}</p></div><button class="quiet" aria-label="Close" @click="activityUser = null"><X :size="18" /></button></div><div class="max-h-[65vh] overflow-y-auto"><ActivityTable :rows="activity.data?.logs || []" :loading="activity.loading" /></div></section></div>
  </main>
</template>
<script setup>
import { createResource } from "frappe-ui"
import { computed, onMounted, ref, watch } from "vue"
import { ExternalLink, UserPlus, X } from "lucide-vue-next"
import ActivityTable from "../components/ActivityTable.vue"
const overview = createResource({ url: "krcti_mhpss.api.system_admin.admin_overview" })
const users = createResource({ url: "krcti_mhpss.api.system_admin.admin_users" })
const saver = createResource({ url: "krcti_mhpss.api.system_admin.admin_save_user", onSuccess: () => { dialogOpen.value = false; load(); loadUsers(0) } })
const activity = createResource({ url: "krcti_mhpss.api.system_admin.admin_user_activity" })
const roles = ref([]), search = ref(""), dialogOpen = ref(false), editing = ref(false), activityUser = ref(null), form = ref({})
let timer
const cards = computed(() => [{ label: "Total users", value: overview.data?.total_users || 0 }, { label: "Active users", value: overview.data?.active_users || 0 }, { label: "Inactive users", value: overview.data?.inactive_users || 0 }, { label: "System administrators", value: overview.data?.system_administrators || 0 }, { label: "KRCTI managers", value: overview.data?.krcti_managers || 0 }, { label: "WoC managers", value: overview.data?.woc_managers || 0 }, { label: "Counsellors", value: overview.data?.counsellors || 0 }])
function load() { overview.submit() }
function loadUsers(start = 0) { users.submit({ search: search.value, start, page_length: 50 }) }
function roleLabel(role) { return ({ "System Manager": "System Administrator", "KRCTI System Administrator": "KRCTI System Administrator", "MHPSS Counsellor": "Counsellor", "KRCTI Programme Manager": "KRCTI Programme Manager", "WoC Programme Manager": "WoC Programme Manager", "MHPSS Client": "Client", "KRCS Data Protection Officer": "Data Protection Officer" })[role] || role || "No application role" }
function dateLabel(value) { return value ? new Date(String(value).replace(" ", "T")).toLocaleString() : "Never" }
function openCreate() { editing.value = false; form.value = { user_type: "System User", role: roles.value.find((r) => r.includes("Counsellor")) || roles.value[0], enabled: true, password: "" }; dialogOpen.value = true }
function openEdit(user) { editing.value = true; form.value = { name: user.name, first_name: user.first_name, last_name: user.last_name, user_type: user.user_type, role: user.roles?.[0] || "", enabled: !!user.enabled }; dialogOpen.value = true }
function saveUser() { saver.submit({ ...form.value, enabled: form.value.enabled ? 1 : 0 }) }
function viewActivity(user) { activityUser.value = user; activity.submit({ user: user.name, start: 0, page_length: 100 }) }
watch(search, () => { clearTimeout(timer); timer = setTimeout(() => loadUsers(0), 250) })
onMounted(async () => { await Promise.all([overview.submit(), users.submit({ start: 0, page_length: 50 })]); roles.value = users.data?.roles || [] })
</script>
<style scoped>
.field{display:block;width:100%;height:42px;border:1px solid #d9dbe0;border-radius:9px;background:#fff;padding:0 11px;color:#33353a;font-size:14px}.field:focus{outline:none;border-color:#c8102e;box-shadow:0 0 0 2px #c8102e22}.label{font-size:13px;font-weight:600;color:#444850}.primary,.secondary,.quiet{display:inline-flex;align-items:center;justify-content:center;gap:7px;border-radius:9px;padding:9px 13px;font-size:13px;font-weight:600}.primary{background:#c8102e;color:#fff}.primary:hover{background:#a10e24}.primary:disabled{opacity:.6}.secondary{border:1px solid #d9dbe0;background:#fff;color:#444850}.quiet{color:#a10e24}.quiet:hover{background:#fce8eb}.tool-link{display:flex;align-items:center;justify-content:space-between;border:1px solid #e4e6ea;border-radius:9px;padding:11px 12px;font-size:13px;font-weight:600;color:#444850}.tool-link:hover{background:#fafafb}
</style>
